   547→    self: &mut Market<MarketType>,
   548→    obligation_id: ID,
   549→    available_repay_coin: Coin<DebtType>,
   550→    coin_decimals_registry: &CoinDecimalsRegistry,
   551→    x_oracle: &XOracle,
   552→    clock: &Clock,
   553→    now: u64,
